#include "stdlib/math/base/special/minmax.h"

/**
* Evaluates the min and max of two values.
*
* @param x   First value
* @param y   Second value
* @return    A double* containing the minimum and maximum values
*
* @example
* double* y = stdlib_base_minmax( 4.0, -5.0 );
* // returns { -5.0, 4.0}
*/


double* stdlib_base_minmax( const double x, const double y ) {
    
    double* result = (double*)malloc(2 * sizeof(double));

    if (x < y) {
        result[0] = x;  
        result[1] = y;  
    } else {
        result[0] = y;
        result[1] = x;  
    }

    return result; 

}
